/** W77-PARAM-WFL PIC 9(01) RECEIVED BY CONTENT: el WFL debe pasar 1. */
@Component
class ParametroCambioDiaValidator implements JobParametersValidator {

    static final long VALOR_EJECUTAR = 1L;

    @Override
    public void validate(JobParameters p) throws JobParametersInvalidException {
        Long valor = p.getLong("paramWfl");
        if (valor == null || valor != VALOR_EJECUTAR) {
            // "VALUE ERRONEO PARA EJECUTAR P075 <valor>" + STATUS := -1
            throw new JobParametersInvalidException("VALUE ERRONEO PARA EJECUTAR P075 " + valor);
        }
    }
}

/** WKS-L080-RESULT PIC 9(02): en Java se conserva el entero completo que devuelve L080. */
public record ResultadoInibatch(int codigo) {
    boolean exitoso() { return codigo == 0; }
}

