/** WS-0101-MENSAJE y MENSAJE-LJ como evento de log estructurado. */
public record MensajeOperacion(String sistema, String paso, String mtp,
                               char tipoDisp, int codigo, String texto) {}

@Component
@RequiredArgsConstructor
class BitacoraOperacion {
    private static final Logger LJ = LoggerFactory.getLogger("LJ");   // antes LJ IN LIBLJ

    void registra(MensajeOperacion m) {
        LJ.atInfo()
          .addKeyValue("sistema", m.sistema()).addKeyValue("paso", m.paso())
          .addKeyValue("mtp", m.mtp()).addKeyValue("codigo", m.codigo())
          .log(m.texto());
    }
}

@Component
@RequiredArgsConstructor
public class CambioDiaTasklet implements Tasklet {

    private final CatalogoVersiones ctlvers;     // DAME_TIT IN CTLVERS
    private final ControlCaptacionL080 l080;     // S500L080CTRL
    private final BitacoraOperacion lj;

    /** 000000-MODULO-DE-CONTROL. El parámetro ya llegó validado (s1). */
    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        String titulo = ctlvers.titulo("S500L080CTRL")
                .orElseThrow(() -> new CambioDiaNoNotificadoException(
                        "ERROR EN CALL CTLVERS S500L080"));   // el fuente solo lo registra
        ResultadoInibatch r = l080.inibatch(titulo);          // 200000-INIBATCH
        if (!r.exitoso()) {
            throw new CambioDiaNoNotificadoException("ERROR EN LLAMADO INIBATCH " + r.codigo());
        }
        return RepeatStatus.FINISHED;
    }
}

/** 10000100-VERSIONES + 20000100-CHECAME-VERSION. */
@Component
@RequiredArgsConstructor
class VersionGuard implements StepExecutionListener {

    private final CatalogoVersiones ctlvers;
    @Value("${s500.p075.id:S500P075}") private String miId;
    @Value("${s500.p075.mtp:25MTP003}") private String miVersion;

    @Override
    public void beforeStep(StepExecution se) {
        long cveError = ctlvers.checame(miId, miVersion);     // S000-CTR-CVEERROR S9(11)
        if (cveError < 0) {
            // ERROR DE VERSION + STATUS := -1. Se decide fallar antes de notificar a P080.
            throw new VersionNoAutorizadaException("ERROR DE VERSION " + cveError);
        }
    }
}

@Service
@RequiredArgsConstructor
public class CatalogoVersiones {

    private final CtlversClient cliente;

    /** 20000100-DAME-TIT-VERS: devuelve el título físico vigente de una librería lógica. */
    public Optional<String> titulo(String libId) {
        var r = cliente.dameTit(libId);                       // GIVING S000-CTR-CVEERROR
        if (r.cveError() != 0) {
            log.error("ERROR EN CALL CTLVERS {} RESULT={}", libId, r.cveError());   // código completo
            return Optional.empty();
        }
        return Optional.of(r.nombreLibreria());               // S000-CTR-NOMLIB X(72)
    }
}

@Service
@RequiredArgsConstructor
public class ControlCaptacionL080 {

    private final L080Gateway gateway;     // adaptador al servicio que reemplace a S500L080CTRL

    /** 205000-INIBATCH-CALL: CALL "S500L080INIBATCHP080 IN S500L080CTRL" GIVING WKS-L080-RESULT. */
    public ResultadoInibatch inibatch(String version) {
        int codigo = gateway.inibatchP080(version);
        if (codigo != 0) {
            log.error("ERROR EN LLAMADO INIBATCH codigo={}", codigo);
        }
        return new ResultadoInibatch(codigo);
    }
}
